Here's a simple function that accepts text and posts it to a Slack channel using the Slack API in JavaScript:

```javascript
const axios = require('axios');

async function postMessageToSlack(text, channel) {
  const url = `https://slack.com/api/chat.postMessage?channel=${channel}`;
  const data = {
    text,
    as_user: true,
  };

  try {
    const response = await axios.post(url, data, {
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${process.env.SLACK_API_KEY}`,
      },
    });

    console.log(`Message posted to Slack channel ${channel}: ${text}`);
    return response.data;
  } catch (error) {
    console.error(`Error posting message to Slack channel ${channel}: ${error}`);
    throw error;
  }
}

// Example usage
postMessageToSlack('Hello, world!', '#general')
  .then((response) => {
    console.log(response);
  })
  .catch((error) => {
    console.error(error);
  });
```

Make sure to replace `'#general'` with the actual channel you want to post the message to. Also, replace `'Bearer <your_slack_api_key>'` with your actual Slack API key.

