import { Schema, Document } from 'mongoose';

export interface User extends Document {
  name: string;
  email: string;
}

const userSchema = new Schema({
  name: { type: String, required: true },
  email: { type: String, required: true },
});

export const UserModel = userSchema.model('User');
```

`order.schema.ts`:

```typescript
import { Schema, Document } from 'mongoose';

export interface Order extends Document {
  product: string;
  quantity: number;
}

const orderSchema = new Schema({
  product: { type: String, required: true },
  quantity: { type: Number, required: true },
});

export const OrderModel = orderSchema.model('Order');
```

3. Create a new Mongoose model that combines both schemas into a single document.

`combined-document.schema.ts`:

```typescript
import { Schema, Document } from 'mongoose';
import { User, UserModel } from './user.schema';
import { Order, OrderModel } from './order.schema';

