  user: User;
  orders: Order[];
}

const combinedDocumentSchema = new Schema({
  user: { type: UserModel, required: true },
  orders: [{ type: OrderModel, required: true }],
});

export const CombinedDocumentModel = combinedDocumentSchema.model('CombinedDocument');
```

