Here's a C++ program that uses a recursive function to generate the Fibonacci sequence, starting with two given integers as the first two sequence elements:

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <stdexcept>

using namespace std;

int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    string input;
    int num1, num2, numElements;

    cout << "Enter the first two integers: ";
    getline(cin, input);

    istringstream iss(input);
    iss >> num1 >> num2;

    if (num1 < 0 || num2 < 0) {
        throw runtime_error("Both integers must be non-negative.");
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> numElements;

    if (numElements <= 0) {
        throw runtime_error("The number of sequence elements must be positive.");
    }

    try {
        int sequence[numElements];
        sequence[0] = num1;
        sequence[1] = num2;

        for (int i = 2; i < numElements; i++) {
            sequence[i] = fibonacci(i, num1, num2);
        }

        cout << "Fibonacci sequence: ";
        for (int i = 0; i < numElements; i++) {
            cout << sequence[i] << ", ";
        }
        cout << endl;
    } catch (exception& e) {
        cerr << "Error: " << e.what() << endl;
    }

    return 0;
}
```

This program prompts the user to enter the first two integers and the number of sequence elements to generate. It then uses a recursive function to generate the Fibonacci sequence and outputs the generated sequence. The program includes error handling for invalid inputs

