```javascript
function searchPlace(sheetName, placeColumn, latColumn, lngColumn) {
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(sheetName);
  var dataRange = sheet.getRange(2, placeColumn, sheet.getLastRow() - 1, 1);
  var data = dataRange.getValues();

  for (var i = 0; i < data.length; i++) {
    var place = data[i][0];
    var url = 'https://maps.googleapis.com/maps/api/geocode/json?address=' + place;
    var response = UrlFetchApp.fetch(url);
    var result = JSON.parse(response);

    if (result.status === 'OK') {
      var lat = result.results[0].geometry.location.lat;
      var lng = result.results[0].geometry.location.lng;
      sheet.getRange(i + 2, latColumn).setValue(lat);
      sheet.getRange(i + 2, lngColumn).setValue(lng);
    } else {
      console.log('Error:', result.status);
    }
  }
}

// Example usage:
searchPlace('Sheet1', 1, 2, 3); // Search for places in column A, store latitude in column B, and longitude in column C
```

