Here's a Go code that uses a table of specific negative words to identify if a given sentence contains a double negative:

```go
package main

import (
	"fmt"
	"strings"
)

var negativeWords = []string{"not", "never", "no", "none", "nothing"}

func isDoubleNegative(sentence string) bool {
	words := strings.Split(sentence, " ")
	for _, word := range words {
		if containsNegativeWord(word) && containsNotBeforeNegativeWord(word) {
			return true
		}
	}
	return false
}

func containsNegativeWord(word string) bool {
	for _, negWord := range negativeWords {
		if strings.ToLower(negWord) == strings.ToLower(word) {
			return true
		}
	}
	return false
}

func containsNotBeforeNegativeWord(word string) bool {
	prevWord := ""
	for _, word := range strings.Split(sentence, " ") {
		if prevWord == "not" && containsNegativeWord(word) {
			return true
		}
		prevWord = word
	}
	return false
}

func main() {
	sentence := "He isn't not worried about the coronavirus situation"
	if isDoubleNegative(sentence) {
		fmt.Println("The sentence contains a double negative.")
	} else {
		fmt.Println("The sentence does not contain a double negative.")
	}
}
```

